133	  queryRpc: JsonRpcProvider,
134	  emitter: EventEmitter,
135	  fetchLatestClaimedEpoch: typeof getLastClaimedEpoch = getLastClaimedEpoch,
136	  fetchBlocksAndCheckFinality: typeof getBlocksAndCheckFinality,
