139	  // Claiming stakes a deposit on the snapshot we are about to read, so resolve
140	  // the settled blocks first and read only at them.
141	  // `queryRpc` is the L1 the inbox's rollup posts batches to (the router on
142	  // arbToGnosis, the outbox itself on arbToEth) and is only valid for that
143	  // Arbitrum->L1 finality math. Every read against `veaOutbox` must instead be
144	  // pinned to a block of the outbox's OWN chain (Chiado on arbToGnosis), whose
145	  // numbering is unrelated to the router's.
146	  const settledBlocks = await fetchSettledReadBlocks({
147	    inboxProvider: transactionHandler.veaInboxProvider,
148	    outboxProvider: queryRpc,
149	    epoch,
